use genex::prelude::*;
use genex::profile::ScopeName;

const PATHS: ScopeName = ScopeName::new("paths");

pub fn wire(game: &mut Game<World>) {
    game.on_update(|sim, ctx| {
        genex::profile_scope!("enemy_paths"); // a suspect, timed
        // The fix for a cpu hitch topped by enemy_paths: at most 8 paths per tick, not all at once.
        let mut done = 0;
        while let Some(id) = sim.world.path_queue.pop_front() {
            sim.world.plan_path(id, ctx);
            done += 1;
            if done == 8 { break; }
        }
        genex::profile::counter(PATHS, done as f64);
    });
}
